function hopDistances(edges, start){
  // BFS-style: return { node: hops } for every node reachable from start (excl. start)
  const dist = {};
  let frontier = [{ node: start, hops: 0 }];
  let iter = 0;
  while (frontier.length){
    if (++iter > 10000) break;
    const next = [];
    for (const f of frontier){
      for (const e of edges){
        if (e.src === f.node){
          dist[e.dst] = f.hops + 1; // record distance to dst
          next.push({ node: e.dst, hops: f.hops + 1 });
        }
      }
    }
    frontier = next;
  }
  return dist;
}

